#!/usr/bin/env bash
# mox lib/playback.sh — sourced by mox.sh at startup
# AUTO-GENERATED by modularize.py — do not edit manually
# shellcheck shell=bash


# ── do_play ─────────────────────────────────────────────────────
do_play() {
  _start
  _check_deps
  local url

  if _is_local_file "${1:-}"; then
    url="$1"
    [[ -f "$url" ]] || { _err "file not found: $url"; return 1; }
    _info "loading local file..."
  elif [[ "${1:-}" =~ ^https?:// ]]; then
    # Direct URL - skip interactive picker (needed for UXI)
    url="$1"
    _info "loading URL..."
  else
    url=$(_pick "${1:-}") || return 1
  fi

  [ -z "$url" ] && { _warn "cancelled"; return; }

  _silent '{"command":["playlist-clear"]}'
  _info "buffering..."
  _ipc_loadfile "$url" "replace"

  # v5-A: _wait_title gives extra time for YouTube URLs (yt-dlp metadata resolution)
  local title; title=$(_wait_title "$url" 60)
  _ok "▶  ${title:-unknown}"
  _log_history "${title:-unknown}" "$(_clean_url "$url")"
  _queue_snapshot
  # v5-R: auto-DJ check after play (background, non-blocking)
  (_autodj_check) &
  disown $! 2>/dev/null
}

# ── do_replay ───────────────────────────────────────────────────
do_replay() {
  [ -s "$HISTORY_FILE" ] || { _warn "history is empty — nothing to replay"; return 1; }

  # Last entry is the most recent: grab its URL (3rd tab-field)
  local last_url last_title
  last_url=$(tail -1 "$HISTORY_FILE" | awk -F'\t' '{print $3}')
  last_title=$(tail -1 "$HISTORY_FILE" | awk -F'\t' '{print $2}')

  [ -z "$last_url" ] && { _warn "could not read last history entry"; return 1; }

  _start
  _silent '{"command":["playlist-clear"]}'
  _info "replaying: ${last_title:-$last_url}..."
  _ipc_loadfile "$last_url" "replace"

  local title; title=$(_wait_title "$last_url" 60)
  _ok "▶  ${title:-${last_title:-unknown}}"
  _log_history "${title:-${last_title:-unknown}}" "$(_clean_url "$last_url")"
  _queue_snapshot
}

# ── do_add_next ─────────────────────────────────────────────────
do_add_next() {
  _start
  _check_deps
  local url

  if _is_local_file "${1:-}"; then
    url="$1"
    [[ -f "$url" ]] || { _err "file not found: $url"; return 1; }
  elif [[ "${1:-}" =~ ^https?:// ]]; then
    # Direct URL - skip interactive picker (needed for UXI)
    url="$1"
  else
    url=$(_pick "${1:-}") || return 1
  fi

  [ -z "$url" ] && { _warn "cancelled"; return; }

  # Get current playing index (0-based), insert at current+1
  local cur_idx; cur_idx=$(_get playlist-playing-pos)
  cur_idx=$(printf '%s' "${cur_idx:-0}" | tr -cd '0-9')
  cur_idx="${cur_idx:-0}"
  local insert_pos=$(( cur_idx + 1 ))

  _ipc_loadfile "$url" "append"
  # Move newly appended track to insert_pos
  local pl_count
  pl_count=$(_cmd '{"command":["get_property","playlist"]}' | "$JQ" '.data|length' 2>/dev/null)
  pl_count=$(printf '%s' "${pl_count:-0}" | tr -cd '0-9')
  pl_count="${pl_count:-0}"
  local last_idx=$(( pl_count - 1 ))
  if [[ "$last_idx" -gt "$insert_pos" ]] 2>/dev/null; then
    _silent "{\"command\":[\"playlist-move\",${last_idx},${insert_pos}]}"
  fi
  _ok "➕ added to play next (position $((insert_pos + 1)))"
  _queue_snapshot
}

# ── do_add ──────────────────────────────────────────────────────
do_add() {
  _start
  _check_deps
  local url

  if _is_local_file "${1:-}"; then
    url="$1"
    [[ -f "$url" ]] || { _err "file not found: $url"; return 1; }
  elif [[ "${1:-}" =~ ^https?:// ]]; then
    # Direct URL - skip interactive picker (needed for UXI)
    url="$1"
  else
    url=$(_pick "${1:-}") || return 1
  fi

  [ -z "$url" ] && { _warn "cancelled"; return; }

  local existing
  existing=$(_cmd '{"command":["get_property","playlist"]}' \
    | "$JQ" -r '.data[].filename' 2>/dev/null | grep -cF "$url" 2>/dev/null)
  # Sanitize: strip non-digits, default to 0 if empty or non-numeric
  existing=$(printf '%s' "${existing:-0}" | tr -cd '0-9')
  existing="${existing:-0}"
  if [[ "$existing" -gt 0 ]] 2>/dev/null; then
    _warn "already in queue — use -f to force add"
    return
  fi

  _ipc_loadfile "$url" "append-play"
  _ok "➕ added to queue"
  _queue_snapshot
}

