# ── do_pause ────────────────────────────────────────────────────
do_pause() {
  _need
  _silent '{"command":["cycle","pause"]}'
  local p; p=$(_get pause)
  [ "$p" = "true" ] && _info "⏸  paused" || _info "▶  resumed"
}

# ── do_next ─────────────────────────────────────────────────────
do_next() {
  _need
  _silent '{"command":["playlist-next"]}'
  local title; title=$(_wait_prop media-title 20)
  [[ -z "$title" || "$title" == *"watch?v="* ]] && { sleep 1; title=$(_get media-title); }
  [[ -n "$title" ]] && _notify_track "$title"
  _ok "⏭  ${title:-end of queue}"
  (_autodj_check) &
  disown $! 2>/dev/null
}

# ── do_prev ─────────────────────────────────────────────────────
do_prev() {
  _need
  _silent '{"command":["playlist-prev"]}'
  local title; title=$(_wait_prop media-title 20)
  [[ -n "$title" ]] && _notify_track "$title"
  _ok "⏮  ${title:-beginning of queue}"
}

# ── do_stop ─────────────────────────────────────────────────────
do_stop() {
  _txt_kill_bg_job
  _sleep_timer_cancel

  # Persist volume/speed before killing
  if [[ -S "$SOCKET" ]]; then
    # Ensure JQ is initialized
    _ensure_bin JQ jq
    if [[ -n "$JQ" ]]; then
      local v s
      v=$(_cmd '{"command":["get_property","volume"]}' 2>/dev/null | "$JQ" -r '.data // empty')
      s=$(_cmd '{"command":["get_property","speed"]}' 2>/dev/null | "$JQ" -r '.data // empty')
      [[ -n "$v" && -n "$s" ]] && printf 'volume=%s\nspeed=%s\n' "$v" "$s" > "$VOLUME_SPEED_STATE" 2>/dev/null
    fi
  fi

  if [[ -f "$MPV_PID_FILE" ]]; then
    local pid; pid=$(cat "$MPV_PID_FILE" 2>/dev/null)
    if [[ -n "$pid" ]] && kill -0 "$pid" 2>/dev/null; then
      kill "$pid" 2>/dev/null
      for i in $(seq 1 20); do
        sleep 0.1
        kill -0 "$pid" 2>/dev/null || break
      done
      kill -9 "$pid" 2>/dev/null
    fi
    rm -f "$MPV_PID_FILE"
  else
    _warn "mpv PID file missing; not killing by process pattern"
  fi
  rm -f "$SOCKET"
  # Only remove lock if we own it or no lock exists
  if [[ -f "$LOCK_FILE" ]]; then
    local lock_pid; lock_pid=$(cat "$LOCK_FILE" 2>/dev/null)
    [[ "$lock_pid" = "$$" || -z "$lock_pid" ]] && { rm -f "$LOCK_FILE"; rmdir "$LOCK_FILE_D" 2>/dev/null; }
  else
    rmdir "$LOCK_FILE_D" 2>/dev/null
  fi
  _ok "stopped"
}

# ── do_start ────────────────────────────────────────────────────
do_start() {
  _start && _ok "daemon ready"
}

# ── do_auto_restart_toggle ──────────────────────────────────────
do_auto_restart_toggle() {
  local current_value="${AUTO_RESTART_DAEMON:-true}"
  
  if [[ "$current_value" == "true" ]]; then
    # Disable auto-restart
    if grep -q "^AUTO_RESTART_DAEMON=" "$CONFIG_FILE" 2>/dev/null; then
      if [[ "$OSTYPE" == "darwin"* ]]; then
        sed -i '' 's/^AUTO_RESTART_DAEMON=.*/AUTO_RESTART_DAEMON=false/' "$CONFIG_FILE"
      else
        sed -i 's/^AUTO_RESTART_DAEMON=.*/AUTO_RESTART_DAEMON=false/' "$CONFIG_FILE"
      fi
    else
      echo "AUTO_RESTART_DAEMON=false" >> "$CONFIG_FILE"
    fi
    _ok "auto-restart disabled — daemon will show error message when unresponsive"
  else
    # Enable auto-restart
    if grep -q "^AUTO_RESTART_DAEMON=" "$CONFIG_FILE" 2>/dev/null; then
      if [[ "$OSTYPE" == "darwin"* ]]; then
        sed -i '' 's/^AUTO_RESTART_DAEMON=.*/AUTO_RESTART_DAEMON=true/' "$CONFIG_FILE"
      else
        sed -i 's/^AUTO_RESTART_DAEMON=.*/AUTO_RESTART_DAEMON=true/' "$CONFIG_FILE"
      fi
    else
      echo "AUTO_RESTART_DAEMON=true" >> "$CONFIG_FILE"
    fi
    _ok "auto-restart enabled — daemon will automatically restart when unresponsive"
  fi
  
  
  # Reload configuration (through sandbox — never source directly)
  _load_config
}

# ── do_seek ─────────────────────────────────────────────────────
do_seek() {
  # Validate input first
  [ -z "${1:-}" ] && { _err "usage: mox seek [+N | -N | N | MM:SS]"; return 1; }
  
  local input="$1"
  local secs="$input"

  # Validate time format first
  if echo "$input" | grep -qE '^[+-]?[0-9]+:[0-9]{2}$'; then
    local sign="" ts="$input"
    [[ "$input" == +* ]] && { sign="+"; ts="${input#+}"; }
    [[ "$input" == -* ]] && { sign="-"; ts="${input#-}"; }
    local m s
    m=$(echo "$ts" | cut -d: -f1 | sed 's/^0*//'); m=${m:-0}
    s=$(echo "$ts" | cut -d: -f2 | sed 's/^0*//'); s=${s:-0}
    # Validate time values
    (( s >= 60 )) && { _err "invalid seek value: $input"; return 1; }
    secs="${sign}$(( m * 60 + s ))"
  fi

  # Validate the final value format
  case "$secs" in
    +*)
      local n="${secs#+}"
      [[ "$n" =~ ^[0-9]+$ ]] || { _err "invalid seek value: $input"; return 1; }
      ;;
    -*)
      local n="${secs#-}"
      [[ "$n" =~ ^[0-9]+$ ]] || { _err "invalid seek value: $input"; return 1; }
      ;;
    *)
      [[ "$secs" =~ ^[0-9]+$ ]] || { _err "invalid seek value: $input"; return 1; }
      ;;
  esac

  _need
  case "$secs" in
    +*)
      local n="${secs#+}"
      _silent "{\"command\":[\"seek\",\"${n}\",\"relative\"]}"
      ;;
    -*)
      local n="${secs#-}"
      _silent "{\"command\":[\"seek\",\"-${n}\",\"relative\"]}"
      ;;
    *)
      [[ "$secs" =~ ^[0-9]+$ ]] || { _err "invalid seek value: $input"; return 1; }
      _silent "{\"command\":[\"seek\",\"$secs\",\"absolute\"]}"
      ;;
  esac

  sleep 0.1
  local pos; pos=$(_get time-pos)
  local dur; dur=$(_get duration)
  pos=$(echo "$pos" | awk '{printf "%d:%02d",$1/60,$1%60}' 2>/dev/null)
  dur=$(echo "$dur" | awk '{printf "%d:%02d",$1/60,$1%60}' 2>/dev/null)

  # v5: mini progress bar after seek
  local pos_i dur_i pct bar_fill bar_empty
  pos_i=$(echo "$pos" | awk -F: '{print $1*60+$2}' 2>/dev/null || echo 0)
  pos_i=$(printf '%s' "${pos_i:-0}" | tr -cd '0-9'); pos_i="${pos_i:-0}"
  dur_i=$(echo "$dur" | awk -F: '{print $1*60+$2}' 2>/dev/null || echo 1)
  dur_i=$(printf '%s' "${dur_i:-1}" | tr -cd '0-9'); dur_i="${dur_i:-1}"
  [[ "$dur_i" -lt 1 ]] 2>/dev/null && dur_i=1
  pct=$(( pos_i * 100 / dur_i ))
  bar_fill=$(printf '%*s' "$(( pct * 20 / 100 ))" '' | tr ' ' '━')
  bar_empty=$(printf '%*s' "$(( 20 - pct * 20 / 100 ))" '' | tr ' ' '─')
  _info "⏩ ${pos} / ${dur}  [${bar_fill}${bar_empty}] ${pct}%"
}

# ── do_speed ────────────────────────────────────────────────────
do_speed() {
  # Validate input first
  case "${1:-}" in
    +|-|r)
      # These are valid, check daemon later
      ;;
    '')  
      { _err "usage: mox speed [0.25-4.0 | + | - | r]"; return 1; } 
      ;;
    *)
      [[ "${1:-}" =~ ^[0-9]+(\.[0-9]+)?$ ]] || { _err "usage: mox speed [0.25-4.0 | + | - | r]"; return 1; }
      (( $(echo "$1 < 0.25" | awk '{print ($1<0.25)?1:0}') )) && { _err "min speed is 0.25"; return 1; }
      (( $(echo "$1 > 4.0"  | awk '{print ($1>4.0)?1:0}') )) && { _err "max speed is 4.0"; return 1; }
      ;;
  esac
  
  _need
  case "${1:-}" in
    +)  _silent '{"command":["multiply","speed",1.1]}' ;;
    -)  _silent '{"command":["multiply","speed",0.909090909]}' ;;
    r)  _silent '{"command":["set_property","speed",1.0]}'; _info "speed: 1.0x"; return ;;
    *)
      _silent "{\"command\":[\"set_property\",\"speed\",$1]}"
      ;;
  esac
  local sp; sp=$(_get speed)
  _info "speed: $(echo "$sp" | awk '{printf "%.3fx",$1}')"
}

